const progressBar = document.querySelector("#quiz-progress-bar");
const scoreText = document.querySelector("#quiz-score");
const feedback = document.querySelector("#quiz-feedback");
feedback.id = "quiz-feedback";
feedback.setAttribute("role", "status");
const originalQuestions = JSON.parse(document.querySelector("#explainer-quiz-data").textContent);
let displayedQuestions = [];
let currentQuestionIndex = 0;
let questionResponses = new Map();
let correctCount = 0;
let incorrectCount = 0;


function shuffle(items) {
  const copy = [...items];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const target = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[target]] = [copy[target], copy[index]];
  }
  return copy;
}

function createAnswerButton(answerIndex, answer) {
  const button = document.createElement("button");
  button.type = "button";
  button.dataset.answerIndex = String(answerIndex);
  button.setAttribute("aria-pressed", "false");
  button.textContent = answer.text;
  return button;
}

function updateStatus() {
  const totalQuestions = displayedQuestions.length;
  progressText.textContent = `Question ${Math.min(currentQuestionIndex + 1, totalQuestions)} of ${totalQuestions}`;
  progressBar.max = totalQuestions;
  progressBar.value = questionResponses.size;
  progressBar.textContent = `${questionResponses.size} of ${totalQuestions}`;
  scoreText.textContent = `Correct: ${correctCount} · Incorrect: ${incorrectCount}`;
}

function updateNavigationButtons() {
  const question = displayedQuestions[currentQuestionIndex];
  const hasAnsweredCurrent = Boolean(question && questionResponses.has(question.id));
  prevButton.hidden = !(hasAnsweredCurrent && currentQuestionIndex > 0);
  nextButton.hidden = !(hasAnsweredCurrent && currentQuestionIndex < displayedQuestions.length - 1);
}

function showFeedback(question, answer) {
  feedback.dataset.visible = "true";
  feedback.dataset.correct = String(answer.correct);
  feedback.textContent = answer.correct
    ? `Correct. ${question.correct_explanation}`
    : `Not quite. ${question.wrong_explanation}`;
  if (currentQuestionIndex >= displayedQuestions.length - 1) {
    feedback.textContent += " Quiz complete.";
  }
}

