  if (currentQuestionIndex >= displayedQuestions.length - 1) {
    feedback.textContent += " Quiz complete.";
  }
}

function revealFeedback(question, answer) {
  requestAnimationFrame(() => {
    updateStatus();
    updateNavigationButtons();
    requestAnimationFrame(() => {
      showFeedback(question, answer);
    });
  });
}

function applyStoredResponse(question, card, response) {
  const answerList = card.querySelector(".answer-list");
  const answer = question.answers[response.answerIndex];
  answerList.querySelectorAll("button").forEach((item, index) => {
    if (index === response.answerIndex) {
      item.dataset.selected = "true";
      item.dataset.correct = String(answer.correct);
      item.setAttribute("aria-pressed", "true");
    }
    item.disabled = true;
  });
  updateNavigationButtons();
  requestAnimationFrame(() => showFeedback(question, answer));
}

