input.new_string:
let correctCount = 0;
let incorrectCount = 0;
let isTransitioning = false;

const prefersReducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function waitForOpacityTransition(element) {
  if (prefersReducedMotion()) return Promise.resolve();
  return new Promise((resolve) => {
    const duration = Number.parseFloat(getComputedStyle(element).transitionDuration) * 1000;
    if (!duration) {
      resolve();
      return;
    }
    let settled = false;
    const finish = () => {
      if (settled) return;
      settled = true;
      element.removeEventListener("transitionend", onTransitionEnd);
      resolve();
    };
    const onTransitionEnd = (event) => {
      if (event.target === element && event.propertyName === "opacity") finish();
    };
    element.addEventListener("transitionend", onTransitionEnd);
    setTimeout(finish, duration + 50);
  });
}

function motionHalfDurationMs() {
  const rootStyles = getComputedStyle(document.documentElement);
  const duration = Number.parseFloat(rootStyles.getPropertyValue("--quiz-motion-duration"));
  return Number.isFinite(duration) ? duration * 500 : 375;
}

function clearFeedback() {
  feedback.dataset.visible = "false";
  feedback.removeAttribute("data-correct");
  feedback.textContent = "";
  feedback.classList.remove("quiz-feedback-fade-out", "quiz-feedback-fade-in", "quiz-feedback-fade-in-active");
}

function showFeedback(question, answer) {

function applyStoredResponse(question, card, response, { revealFeedbackBlock = true } = {}) {
  const answerList = card.querySelector(".answer-list");
  const answer = question.answers[response.answerIndex];
  answerList.querySelectorAll("button").forEach((item, index) => {
    if (index === response.answerIndex) {
      item.dataset.selected = "true";
      item.dataset.correct = String(answer.correct);
      item.setAttribute("aria-pressed", "true");
    }
    item.disabled = true;
  });
  updateNavigationButtons();
  if (revealFeedbackBlock) requestAnimationFrame(() => showFeedback(question, answer));
}

function buildQuestionCard(question) {
  const card = document.createElement("section");
  card.className = "quiz-question";
  const heading = document.createElement("h3");
  heading.textContent = `${currentQuestionIndex + 1}. ${question.prompt}`;
  const answers = document.createElement("div");
  answers.className = "answer-list";
  question.answers.forEach((answer, answerIndex) => {
    answers.append(createAnswerButton(answerIndex, answer));
  });
  answers.querySelectorAll("button").forEach((button) => {
    button.setAttribute("aria-describedby", feedback.id);
  });
  card.append(heading, answers);
  return card;
}

async function transitionFeedbackForQuestion(question) {
  const response = questionResponses.get(question.id);
  const wasVisible = feedback.dataset.visible === "true";

  if (prefersReducedMotion()) {
    if (response) showFeedback(question, question.answers[response.answerIndex]);
    else clearFeedback();
    return;
  }

  const halfDuration = motionHalfDurationMs();

  if (wasVisible) {
    feedback.classList.add("quiz-feedback-fade-out");
    await wait(halfDuration);
  }

  if (response) {
    showFeedback(question, question.answers[response.answerIndex]);
    feedback.classList.remove("quiz-feedback-fade-out");
    feedback.classList.add("quiz-feedback-fade-in");
    feedback.offsetHeight;
    feedback.classList.add("quiz-feedback-fade-in-active");
    await wait(halfDuration);
    feedback.classList.remove("quiz-feedback-fade-in", "quiz-feedback-fade-in-active");
    return;
  }

  clearFeedback();
  feedback.classList.remove("quiz-feedback-fade-out");
}

async function renderQuestion({ animate = false } = {}) {
  const question = displayedQuestions[currentQuestionIndex];
  if (!question) return;

  updateStatus();
  const existing = quizRoot.querySelector(".quiz-question:not(.quiz-question-exit)");
  const nextCard = buildQuestionCard(question);
  const shouldAnimate = animate && existing && !prefersReducedMotion();

  if (shouldAnimate) {
    isTransitioning = true;
    prevButton.disabled = true;
    nextButton.disabled = true;
    quizRoot.style.minHeight = `${quizRoot.offsetHeight}px`;
    existing.classList.add("quiz-question-exit");
    nextCard.classList.add("quiz-question-enter");
    quizRoot.append(nextCard);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        nextCard.classList.add("quiz-question-enter-active");
      });
    });

    await Promise.all([
      waitForOpacityTransition(existing),
      waitForOpacityTransition(nextCard),
      transitionFeedbackForQuestion(question),
    ]);

    existing.remove();
    nextCard.classList.remove("quiz-question-enter", "quiz-question-enter-active");
    quizRoot.style.minHeight = "";
    isTransitioning = false;
  } else {
    quizRoot.replaceChildren();
    clearFeedback();
    quizRoot.append(nextCard);
    const response = questionResponses.get(question.id);
    if (response) {
      applyStoredResponse(question, nextCard, response);
    } else {
      updateNavigationButtons();
    }
    return;
  }

  const response = questionResponses.get(question.id);
  if (response) applyStoredResponse(question, nextCard, response, { revealFeedbackBlock: false });
  else updateNavigationButtons();
}

