  panel.dataset.visible = "true";
  panel.dataset.correct = String(answer.correct);
  panel.textContent = formatFeedbackText(question, answer);
}

function buildFeedbackPanel(question, response) {
  const panel = document.createElement("div");
  panel.className = "feedback";
  panel.setAttribute("role", "status");
  if (response) populateFeedbackPanel(panel, question, question.answers[response.answerIndex]);
  else panel.dataset.visible = "false";
  return panel;
}

function measureFeedbackPanelHeight(panel) {
