/* Reserve the tallest question card and feedback panel so the quiz block never resizes. */
function reserveQuizSpace() {
  if (displayedQuestions.length === 0) return;
  let cardHeight = 0;
  let panelHeight = 0;
  displayedQuestions.forEach((question, index) => {
    cardHeight = Math.max(cardHeight, measureHiddenHeight(quizRoot, buildQuestionCard(question, index)));
    const outcomes = [
      question.answers.findIndex((answer) => answer.correct),
      question.answers.findIndex((answer) => !answer.correct),
    ];
    outcomes.forEach((answerIndex) => {
      if (answerIndex < 0) return;
      const panel = buildFeedbackPanel(question, { answerIndex }, index);
      panelHeight = Math.max(panelHeight, measureHiddenHeight(feedbackStack, panel));
    });
  });
  quizRoot.style.minHeight = `${cardHeight}px`;
  feedbackStack.style.minHeight = `${panelHeight}px`;
}

