async page => {
  const sleep = (ms) => page.waitForTimeout(ms);
  await page.goto('http://127.0.0.1:8898/2026-08-21_06-00-00_explanation-scope-governor-skill.html');
  await page.setViewportSize({ width: 1100, height: 950 });
  const click = (sel) => page.evaluate((s) => document.querySelector(s).click(), sel);
  const answer = () => page.evaluate(() => document.querySelector('#explainer-quiz .answer-list button').click());
  const sample = () => page.evaluate(() => ({
    quiz: Math.round(document.querySelector('.quiz').getBoundingClientRect().height),
    page: Math.round(document.documentElement.scrollHeight),
    questionRegion: Math.round(document.querySelector('#quiz-question-region').getBoundingClientRect().height),
    feedbackRegion: Math.round(document.querySelector('#quiz-feedback-region').getBoundingClientRect().height),
    cardTop: Math.round(document.querySelector('#explainer-quiz .quiz-question:not(.quiz-question-exit)').getBoundingClientRect().top),
    panels: document.querySelectorAll('#quiz-feedback-stack .feedback').length,
    liveText: document.querySelector('#quiz-feedback').textContent.slice(0, 30),
    reserved: {
      quiz: document.querySelector('#explainer-quiz').style.minHeight,
      stack: document.querySelector('#quiz-feedback-stack').style.minHeight,
    },
  }));

  const report = { walk: [] };
  report.walk.push({ at: 'initial', ...(await sample()) });
  // answer all 10, sampling after each answer and each advance
  for (let i = 0; i < 10; i += 1) {
    await answer();
    await sleep(820);
    report.walk.push({ at: `answered-${i + 1}`, ...(await sample()) });
    if (i < 9) {
      await click('#quiz-next');
      await sleep(820);
      report.walk.push({ at: `moved-${i + 2}`, ...(await sample()) });
    }
  }
  // back and forth
  for (const sel of ['#quiz-prev', '#quiz-prev', '#quiz-next']) {
    await click(sel);
    await sleep(820);
    report.walk.push({ at: sel, ...(await sample()) });
  }
  report.uniqueQuiz = [...new Set(report.walk.map((s) => s.quiz))];
  report.uniquePage = [...new Set(report.walk.map((s) => s.page))];
  report.uniqueCardTop = [...new Set(report.walk.map((s) => s.cardTop))];
  report.uniqueFeedbackRegion = [...new Set(report.walk.map((s) => s.feedbackRegion))];
  report.reserved = report.walk[0].reserved;
  report.sampleRow = report.walk[3];
  delete report.walk;
  return JSON.stringify(report, null, 1);
}

