async page => {
  await page.goto('http://127.0.0.1:8898/2026-08-21_06-00-00_explanation-scope-governor-skill.html');
  await page.setViewportSize({ width: 1100, height: 950 });
  const answer = () => page.evaluate(() => document.querySelector('#explainer-quiz .answer-list button').click());
  await answer();
  await page.waitForTimeout(1100);
  await page.evaluate(() => document.querySelector('#quiz-next').click());
  await page.waitForTimeout(1100);
  await answer();
  await page.waitForTimeout(1100);

  // sample the crossfade opacity ramp on the way back to an answered question
  const ramp = await page.evaluate(async () => {
    const samples = [];
    const start = performance.now();
    document.querySelector('#quiz-prev').click();
    await new Promise((resolve) => {
      const tick = () => {
        const entering = document.querySelector('#explainer-quiz .quiz-question.quiz-question-enter');
        const panel = document.querySelector('#quiz-feedback-stack .feedback:not(.quiz-feedback-exit)');
        samples.push({
          t: Math.round(performance.now() - start),
          card: entering ? Number(getComputedStyle(entering).opacity).toFixed(3) : null,
          feedback: panel ? Number(getComputedStyle(panel).opacity).toFixed(3) : null,
        });
        if (performance.now() - start > 1000) resolve();
        else requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });
    return samples;
  });

  const at = (ms) => ramp.reduce((best, s) => (Math.abs(s.t - ms) < Math.abs(best.t - ms) ? s : best));
  return JSON.stringify({
    duration: await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--quiz-motion-duration').trim()),
    easing: await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--quiz-motion-ease').trim()),
    curve: [100, 225, 450, 675, 800, 900, 980].map((ms) => at(ms)),
  }, null, 1);
}

